            bits.push(style.paint(icon));
            bits.push(style.paint(" ".repeat(spaces_count as usize)));
        }

        if self.file.parent_dir.is_none() && self.options.absolute == Absolute::Off {
            if let Some(parent) = self.file.path.parent() {
